function hash(s){let h=0;for(const c of s)h=(Math.imul(h,31)+c.charCodeAt(0))>>>0;return h;}
export function pixelAvatar(id,color='#dc2626'){
 const seed=hash(id),skin=['#f3c7a2','#dca47e','#e8b88f'][seed%3],hair=['#151515','#35261f','#20202b'][seed%3];
 return `<svg viewBox="0 0 40 40" aria-hidden="true" shape-rendering="crispEdges"><circle cx="20" cy="20" r="20" fill="${color}"/><path d="M9 12h22v17H9z" fill="${skin}"/><path d="M8 11h24v8h-5v-4H13v4H8z" fill="${hair}"/><path d="M14 21h4v3h-4zm10 0h4v3h-4z" fill="#171717"/><path d="M17 28h8v3h-8z" fill="#7f4c3c"/><path d="M8 33h24v7H8z" fill="#e6e6e6"/><path d="M16 33h8v7h-8z" fill="${color}"/></svg>`;
}
export function officeSvg(){
 let city='',x=0;
 for(let i=0;x<1600;i++){const w=40+hash('building'+i)%70,h=120+hash('height'+i)%300;city+=`<rect x="${x}" y="${640-h}" width="${w}" height="${h}" fill="#0c1a28"/>`;for(let wy=652-h;wy<630;wy+=18)for(let wx=x+6;wx<x+w-6;wx+=12)if(hash('window'+wx+wy)%5===0)city+=`<rect x="${wx}" y="${wy}" width="5" height="7" fill="#ffd27a" opacity=".42"/>`;x+=w+6;}
 return `<svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="office-sky" x2="0" y2="1"><stop stop-color="#090f18"/><stop offset="1" stop-color="#182336"/></linearGradient><linearGradient id="office-floor" x2="0" y2="1"><stop stop-color="#171e26"/><stop offset="1" stop-color="#090d11"/></linearGradient></defs><rect width="1600" height="900" fill="#111922"/><rect x="330" y="70" width="940" height="560" fill="url(#office-sky)"/>${city}<circle cx="1120" cy="170" r="40" fill="#e8e4da" opacity=".08"/><g stroke="#26323d" stroke-width="10" fill="none"><rect x="330" y="70" width="940" height="560"/><path d="M643 70v560M957 70v560"/></g><rect y="640" width="1600" height="260" fill="url(#office-floor)"/><path d="M0 640h1600" stroke="#293b48" stroke-width="3"/><path d="M40 560h380l40 40v220h-30V610H70v210H40z" fill="#1d2833" stroke="#2c3b4a" stroke-width="2"/><rect x="120" y="470" width="170" height="90" fill="#0c1218" stroke="#33465a" stroke-width="3"/><rect x="128" y="478" width="154" height="74" fill="#dc2626" opacity=".2"/><rect x="196" y="560" width="18" height="10" fill="#33465a"/><rect x="310" y="535" width="60" height="25" fill="#2a3644"/><rect x="1330" y="250" width="240" height="560" fill="#141d26" stroke="#2c3b4a" stroke-width="3"/><path d="M1330 390h240m-240 140h240m-240 140h240" stroke="#2c3b4a" stroke-width="3"/><g fill="#c5a44c"><path d="M1380 330h40v10q0 30-20 30t-20-30zm14 40h12v12h-12zm-8 12h28v6h-28zM1480 470h34v8q0 26-17 26t-17-26zm11 34h12v12h-12zm-7 12h26v6h-26z"/></g></svg>`;
}
const dock=[['home','home','로비/집무실','Lobby'],['squad','users','선수단/훈련','Squad'],['market','market','이적시장','Transfer'],['training','training','전술/스크림','Tactics'],['finance','wallet','구단/시설','Club'],['history','trophy','전시장','Trophies'],['league','table','리그/일정','League']];
export function shellMarkup(c,body){
 const {state:s,E,t,esc,icon,teamIcon,fmtDate,nav,ui}=c,mine=t(s.myTeam),ps=E.lineup(s,s.myTeam),fat=ps.reduce((n,p)=>n+p.fatigue,0)/Math.max(1,ps.length),next=E.nextOwnMatch(s),week=Math.floor(E.dayDistance(`${s.year}-01-01`,s.date)/7)+1,net=(mine.support+mine.sponsor-E.roster(s).reduce((n,p)=>n+p.salary,0))/52-.16;
 const urgent=next&&next.date<=s.date;const dday=next?(urgent?'D-DAY':`D-${E.dayDistance(s.date,next.date)}`):s.seasonComplete?'OFF':'D-'+Math.max(0,E.dayDistance(s.date,`${s.year}-01-12`));
 const news=s.news.slice(0,12).map(n=>`<span><b>[${esc(n.title)}]</b> ${esc(n.body)}</span>`).join('');
 const menu=ui.menu?`<div class="vct-quick-menu">${[['home','로비/집무실'],['squad','선수단'],['training','훈련 센터'],['market','이적시장'],['calendar','시즌 일정'],['league','리그 순위'],['champions','챔피언 연구실'],['finance','구단 재정'],['history','기록실'],['settings','설정 · 저장']].map(([id,name])=>`<button data-action="nav" data-id="${id}">${name}</button>`).join('')}</div>`:'';
 const isStage=['draft','draft-reference','viewer'].includes(nav);
 return `<div class="vct-shell ${isStage?'match-mode':''} ${nav==='home'?'is-lobby':''}"><div class="office-background">${officeSvg()}</div><header class="vct-top"><div class="vct-identity">${teamIcon(s.myTeam)}<div><strong>${esc(mine.name)}</strong><span>LCK | 파트너 팀 | <i>구단주</i></span><div class="vct-reputation">명성 <b>${mine.reputation}</b> | 팬 <b>${(mine.fan??0).toLocaleString('ko-KR')}</b></div></div></div><div class="vct-season"><strong>${s.year} ${esc(s.phase.title)} - WEEK ${week}</strong><small>${fmtDate(s.date)} | ${urgent?'경기':E.PROGRAMS[s.trainingPlan[(new Date(s.date+'T12:00:00Z').getUTCDay()+6)%7]]}</small></div><button class="vct-calendar-button" data-action="nav" data-id="calendar" aria-label="시즌 일정">${icon('calendar')}</button><div class="vct-dday"><b>${dday}</b><small>${next?esc(next.competition+' '+next.round):s.seasonComplete?'시즌 결산':'LCK CUP 준비'}</small></div><div class="vct-fatigue ${fat>70?'tired':''}"><small>팀 피로</small><b>${Math.round(fat)}</b><span>${fat>80?'과로':fat>45?'피곤':'양호'}</span></div><div class="vct-money"><strong>${mine.budget.toFixed(1)}억원</strong><small class="${net>=0?'mint':'red'}">주간 ${net>=0?'+':''}${Math.round(net*10000).toLocaleString('ko-KR')}만원</small></div><button class="vct-icon-button" data-action="menu" aria-label="전체 메뉴">${icon('menu')}</button><button class="vct-icon-button" data-action="nav" data-id="settings" aria-label="저장 및 설정">${icon('save')}</button></header>${menu}<main class="vct-workspace">${body}</main><nav class="vct-dock" aria-label="구단 관리 메뉴">${dock.map(([id,ico,label,english])=>`<button class="${nav===id?'active':''}" data-action="nav" data-id="${id}" ${nav===id?'aria-current="page"':''}>${icon(ico)}<strong>${label}</strong><small>${english}</small></button>`).join('')}</nav><div class="vct-ticker"><span class="ticker-label">NEWS›</span><div class="ticker-track">${news||`<span>${E.database().season?.startYear??2022} 선수 · ${E.database().season?.competitionFormat??2025} LCK 대회 형식 · 당신의 커리어를 시작하세요.</span>`}</div></div></div>`;
}
export function lobbyMarkup(c){
 const {state:s,E,t,esc,icon,btn,badge,topChampions,img}=c,mine=t(s.myTeam),ps=E.lineup(s,s.myTeam),today=E.todayOwnMatch(s),next=E.nextOwnMatch(s),pre=s.phase.key==='PRESEASON',off=s.seasonComplete,latest=s.news[0];
 let go=off?['다음 시즌 준비','next-season','스토브리그 · 로스터 정비']:pre?['시즌 시작','start-season',`${E.database().season?.startYear??2022} 로스터 확정 · LCK CUP`]:today?['공식 경기 시작','prepare',`${today.competition} · BO${today.bestOf}`]:['다음 일정 진행','advance',`오늘: ${E.PROGRAMS[s.trainingPlan[(new Date(s.date+'T12:00:00Z').getUTCDay()+6)%7]]}`];
 const currentWeek=(new Date(s.date+'T12:00:00Z').getUTCDay()+6)%7;
 return `<h1 class="sr-only">구단 대시보드</h1><section class="vct-side vct-left ${s.uiLeftClosed?'closed':''}"><header><h2>ROSTER & STAFF</h2><button data-action="toggle-panel" data-id="left" aria-label="선수단 패널 접기">${s.uiLeftClosed?'›':'‹'}</button></header><div class="vct-panel-body"><h3>주전 5인</h3>${ps.map(p=>`<button class="vct-player" data-action="player" data-id="${p.id}"><span class="pixel-avatar" title="게임용 선수 아바타">${pixelAvatar(p.id,mine.color)}</span><span class="vct-player-main"><span class="vct-player-name"><i>${p.position}</i> ${esc(p.name)}</span><span class="vct-player-condition">컨디 <b>${100-Math.round(p.fatigue)}</b>　사기 <b>${Math.round(p.morale)}</b>　${E.ROLE_NAMES[p.position]}</span></span><span class="vct-player-end"><span class="fatigue-tag ${p.fatigue>70?'bad':''}">피로 ${Math.round(p.fatigue)} ${p.fatigue>70?'과로':p.fatigue>45?'피곤':'양호'}</span><b>${p.ovr}<small>OVR</small></b></span></button>`).join('')}<h3>코칭스태프 · 팀 전력</h3><div class="vct-staff">${[['users','코칭',`Lv.${mine.coach}`],['table','전술',s.strategy==='early'?'공격':s.strategy==='late'?'성장':'균형'],['champion','팀 합',Math.round(mine.synergy)],['training','시설',`Lv.${mine.facility}`]].map(([ico,name,value])=>`<button data-action="nav" data-id="training">${icon(ico)}<span>${name}</span><b>${value}</b></button>`).join('')}</div><div class="spread"><h3>코치 한마디</h3><button data-action="nav" data-id="champions" class="section-link">챔피언 연구실</button></div><div class="coach-line">${badge(ps.some(p=>p.fatigue>75)?'긴급':'참고',ps.some(p=>p.fatigue>75)?'red':'')}<span>${ps.some(p=>p.fatigue>75)?'선수 피로가 높습니다. 휴식을 배치하세요.':`팀 합 ${Math.round(mine.synergy)} · 숙련과 조합을 함께 점검하세요.`}</span></div><div class="coach-line">${badge('추천','mint')}<span>피어리스 대비 역할별 챔피언 폭 확보</span></div><button class="coach-button" data-action="coach-plan">코치 추천 7일 일정 적용</button></div><footer>${btn('로스터 관리','nav','data-id="squad"','ghost')}${btn('이적시장','nav','data-id="market"','primary')}</footer></section><section class="vct-side vct-right ${s.uiRightClosed?'closed':''}"><header><button data-action="toggle-panel" data-id="right" aria-label="관리 패널 접기">${s.uiRightClosed?'‹':'›'}</button><h2>MANAGEMENT</h2></header><div class="vct-panel-body"><h3>구단 수입</h3>${[['ORGANIZATION SUPPORT','구단 지원금',mine.support],['PARTNER SPONSOR','스폰서 수입',mine.sponsor]].map(([title,name,amount])=>`<button class="vct-sponsor" data-action="nav" data-id="finance"><span><strong>${title}</strong><b>${Math.round(amount/52*10000).toLocaleString()}만원/주</b></span><small>${name} · 연 ${amount}억원</small><i style="width:${Math.min(100,amount)}%"></i></button>`).join('')}<h3>시설 등급</h3><div class="vct-facilities">${[['코칭 스태프',mine.coach],['훈련 시설',mine.facility],['팀 합',Math.max(1,Math.round(mine.synergy/20))]].map(([name,lv])=>`<button data-action="nav" data-id="training"><span>${name}</span><b>Lv.${lv}</b><div>${Array.from({length:5},(_,i)=>`<i class="${i<lv?'on':''}"></i>`).join('')}</div></button>`).join('')}</div><div class="spread"><h3>이번 주 일정</h3><button data-action="nav" data-id="calendar" class="section-link">전체 보기</button></div><div class="vct-week">${s.trainingPlan.map((p,i)=>`<button class="${i===currentWeek?'today':''}" data-action="nav" data-id="training"><b>${['월','화','수','목','금','토','일'][i]}</b><span class="program-${p}">${i===currentWeek&&today?'경기':p==='balanced'?'훈련':p==='champion'?'챔피언':p==='scrim'?'스크림':p==='rest'?'휴식':'기량'}</span>${i===currentWeek?'<small>TODAY</small>':''}</button>`).join('')}</div><p class="vct-helper">챔피언 숙련 · 팀 합 · 피로를 균형 있게 관리하세요.</p><h3>다음 상대</h3><div class="vct-next">${next?`<strong>${esc(t(next.teams.find(id=>id!==s.myTeam)).name)}</strong><span>${next.date} · BO${next.bestOf}</span><button data-action="nav" data-id="league">대진 · 전체 기록</button>`:'<span>시즌을 시작하면 일정이 생성됩니다.</span>'}</div><h3>선수별 챔피언</h3><div class="vct-comfort">${ps.slice(0,3).map(p=>`<button data-action="player" data-id="${p.id}"><strong>${esc(p.name)}</strong><span>${topChampions(p,3).map(x=>img(x.c.id)).join('')}</span></button>`).join('')}</div></div></section><div class="vct-brief"><span class="brief-person">${icon('users')}</span><div><span class="brief-label">비서 브리핑</span><p>${esc(latest?.body??'주전과 훈련 계획을 확인하고 시즌을 시작하세요.')}</p><span class="brief-date">${esc(latest?.date??s.date)} · ${s.news.length}개 구단 소식</span></div></div><div class="vct-progression"><div class="vct-auto-actions">${btn('자동 진행','auto-dialog','','ghost')}${!pre&&!off?btn('7일 진행','advance','data-days="7"','ghost'):''}</div><button class="vct-go" data-action="${go[1]}" ${today?`data-id="${today.id}"`:''} data-days="1"><strong>${go[0]}</strong><small>${esc(go[2])}</small></button>${!pre&&!off?btn('다음 경기까지','next-match','','ghost'):''}</div>`;
}
